<script setup>
import { ref, computed, onMounted, onBeforeUnmount, nextTick } from 'vue';
import { Chart, LineController, LineElement, PointElement, LinearScale, CategoryScale, Tooltip } from 'chart.js';
import { api, send, session } from './api';
Chart.register(LineController, LineElement, PointElement, LinearScale, CategoryScale, Tooltip);
Chart.defaults.font.size = 13;
Chart.defaults.font.family = "Manrope, Vazirmatn, sans-serif";
const progress = ref(null), plans = ref([]), links = ref([]), error = ref(''), message = ref(''), loading = ref(true), busy = ref(false), chartElement = ref(null);
const weight = ref(''), waist = ref(''), date = ref(new Date().toISOString().slice(0,10)), days = ref(90);
let chart;
const latest = computed(() => progress.value?.measurements.at(-1));
const difference = computed(() => { const a=progress.value?.measurements||[];return a.length>1?(a.at(-1).weightKg-a[0].weightKg).toFixed(1):null; });
const todayKcal = computed(() => (progress.value?.meals||[]).filter(x=>x.recordedAt.slice(0,10)===new Date().toISOString().slice(0,10)).reduce((a,x)=>a+x.kcal,0));
async function load() {
  error.value=''; loading.value=true;
  try { [progress.value, plans.value, links.value] = await Promise.all([api('/progress?days='+days.value),api('/plans'),api('/links')]); await nextTick(); draw(); }
  catch(e){error.value=e.message;} finally {loading.value=false;await nextTick();draw();}
}
function draw(){if(!chartElement.value||!progress.value)return;chart?.destroy();chart=new Chart(chartElement.value,{type:'line',data:{labels:progress.value.measurements.map(x=>new Date(x.recordedAt).toLocaleDateString(undefined,{month:'short',day:'numeric'})),datasets:[{label:'Weight (kg)',data:progress.value.measurements.map(x=>x.weightKg),borderColor:'#325b44',backgroundColor:'#d6f36b',pointRadius:5,tension:.25}]},options:{responsive:true,maintainAspectRatio:false,scales:{y:{title:{display:true,text:'Weight (kg)'},beginAtZero:false}},plugins:{legend:{display:false}}}});}
async function morePlans(){try{plans.value.push(...await api('/plans?after='+(plans.value.at(-1)?.id||0)));}catch(e){error.value=e.message;}}
async function moreLinks(){try{links.value.push(...await api('/links?before='+(links.value.at(-1)?.id||2147483647)));}catch(e){error.value=e.message;}}
async function save(){busy.value=true;error.value='';message.value='';try{await send('/measurements',{weightKg:Number(weight.value),waistCm:waist.value?Number(waist.value):null,recordedAt:new Date(date.value+'T00:00:00Z').toISOString(),requestId:crypto.randomUUID()});message.value='Measurement saved.';weight.value='';waist.value='';await load();}catch(e){error.value=e.message;}finally{busy.value=false;}}
async function relationship(link,status){busy.value=true;try{await send('/links/'+link.id,{status},'PUT');await load();}catch(e){error.value=e.message;}finally{busy.value=false;}}
async function complete(plan){busy.value=true;try{await send('/plans/'+plan.id+'/complete',{requestId:crypto.randomUUID()});message.value='Workout recorded. Well done for showing up.';await load();}catch(e){error.value=e.message;}finally{busy.value=false;}}
function content(plan){try{return JSON.parse(plan.contentJson);}catch{return null;}}
onMounted(load);onBeforeUnmount(()=>chart?.destroy());
</script>
<template>
  <div class="page-heading"><div><p class="eyebrow">YOUR EVERYDAY STARTING POINT</p><h1>Hello, {{ session.user.displayName || 'there' }}<span class="lime-dot">.</span></h1><p>A clear view of where you are, and what comes next.</p></div><span class="tag">{{ new Date().toLocaleDateString(undefined,{month:'long',day:'numeric',year:'numeric'}) }}</span></div>
  <p v-if="error" class="notice error" role="alert">{{ error }} <button class="text-button" @click="load">Retry</button></p><p v-if="message" class="notice" role="status">{{ message }}</p>
  <div v-if="loading && !progress" class="card" role="status">Loading your records…</div>
  <template v-else>
    <div class="stat-grid"><div class="stat card lime"><span>Latest weight</span><strong>{{ latest?.weightKg ?? '—' }}<small>kg</small></strong><p>{{ latest ? 'Your most recent entry' : 'Add your first measurement' }}</p></div><div class="stat card"><span>Weight change</span><strong>{{ difference===null?'—':(Number(difference)>0?'+':'')+difference }}<small>kg</small></strong><p>Over the selected period</p></div><div class="stat card"><span>Workouts recorded</span><strong>{{ progress?.workouts.length || 0 }}</strong><p>Every completed session counts</p></div><div class="stat card"><span>Food logged today · UTC</span><strong>{{ Math.round(todayKcal) }}<small>kcal</small></strong><p>Logged meals, not a daily target</p></div></div>
    <div class="two-column"><section class="card"><div class="section-heading"><div><p class="eyebrow">SEE THE BIGGER PICTURE</p><h2>Your progress</h2></div><label class="compact-label">Period<select v-model="days" @change="load"><option :value="30">30 days</option><option :value="90">90 days</option><option :value="366">1 year</option></select></label></div><div v-if="progress?.measurements.length" class="chart"><canvas ref="chartElement" role="img" aria-label="Weight history chart. Exact values are in the table below."></canvas></div><div v-else class="empty"><span>→</span><h3>Your story starts with one entry.</h3><p>Add a measurement to see your progress here.</p></div><details v-if="progress?.measurements.length"><summary>View exact measurements</summary><div class="table-scroll"><table><thead><tr><th>Date</th><th>Weight</th><th>Waist</th></tr></thead><tbody><tr v-for="m in progress.measurements" :key="m.id"><td>{{new Date(m.recordedAt).toLocaleDateString()}}</td><td>{{m.weightKg}} kg</td><td>{{m.waistCm ?? '—'}}</td></tr></tbody></table></div></details><p class="hint">Up to 1,000 records per series. Weight alone does not measure overall health.</p></section>
      <form class="card" @submit.prevent="save"><p class="eyebrow">A MOMENT TO CHECK IN</p><h2>Record a measurement</h2><label>Date<input v-model="date" type="date" required :max="new Date().toISOString().slice(0,10)"></label><div class="field-row"><label>Weight · kg<input v-model="weight" type="number" min="20" max="400" step="0.1" inputmode="decimal" placeholder="e.g. 72.5" required></label><label>Waist · cm <small>optional</small><input v-model="waist" type="number" min="30" max="250" step="0.1" inputmode="decimal" placeholder="e.g. 82"></label></div><p class="hint">Only you and coaches whose invitation you accept can view these records.</p><button class="primary wide" :disabled="busy||!session.user.healthDataConsentAt">Save measurement →</button></form></div>
    <section class="card"><div class="section-heading"><div><p class="eyebrow">ONE STEP AT A TIME</p><h2>Your coach’s plans</h2></div><RouterLink class="text-button" to="/exercises">Explore exercises →</RouterLink></div><p v-if="!plans.length" class="muted">Your coach can assign a plan after you accept their invitation below. Meanwhile, explore the free exercise library and food calculator.</p><div class="plan-grid"><article v-for="p in plans" :key="p.id" class="plan"><span class="tag">{{p.kind}}</span><h3>{{p.title}}</h3><p class="hint">Assigned {{new Date(p.createdAt).toLocaleDateString()}}</p><template v-if="p.kind==='Workout'"><ul><li v-for="(e,i) in content(p)" :key="i"><a :href="'/exercises/#'+e.exerciseId">{{e.exerciseId}}</a> · {{e.sets}} × {{e.reps}} · {{e.restSeconds}} sec rest</li></ul><button :disabled="busy" @click="complete(p)">Record a completed session</button></template><template v-else><p><strong>{{Math.round(content(p)?.kcal||0)}} kcal</strong> · {{content(p)?.protein}} g protein</p><ul><li v-for="(f,i) in content(p)?.items" :key="i">{{f.name}} · {{f.grams}} g</li></ul></template></article></div><button v-if="plans.length&&plans.length%50===0" class="text-button" @click="morePlans">Load more plans</button></section>
    <section class="card"><p class="eyebrow">YOU CONTROL THE CONNECTION</p><h2>Your coaches</h2><p class="muted">Accepting an invitation shares your measurements, food diary and assigned plans with that coach. You can revoke access here at any time.</p><div v-for="l in links.filter(x=>x.studentId===session.user.id)" :key="l.id" class="relationship"><div><strong>{{l.coachName}}</strong><span class="tag">{{l.status}}</span></div><div class="actions"><template v-if="l.status!=='Active'"><button :disabled="busy" @click="relationship(l,'Active')">Accept & share records</button><button v-if="l.status==='Pending'" class="secondary" :disabled="busy" @click="relationship(l,'Declined')">Decline</button></template><button v-else class="secondary" :disabled="busy" @click="relationship(l,'Revoked')">Revoke access</button></div></div><button v-if="links.length&&links.length%100===0" class="text-button" @click="moreLinks">Load more relationships</button><p v-if="!links.some(x=>x.studentId===session.user.id)" class="hint">No invitations yet. Ask your coach to invite the email address you registered with.</p></section>
  </template>
</template>
